import * as THREE from 'three';
import {sampleSurface,validateSurface} from './nurbs.js';
import {presets} from './surfaces.js';

const $=id=>document.getElementById(id), params=new URLSearchParams(location.search);
const canvas=$('viewer'), renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.setClearColor(0x000000,0);
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(36,1,.01,100),stereoCamera=new THREE.StereoCamera(); camera.position.z=7; stereoCamera.eyeSep=.22;
const rotation=new THREE.Matrix4(), baseRotation=new THREE.Matrix4();
rotation.identity(); rotatePlane(0,3,.62); rotatePlane(1,3,-.28); rotatePlane(0,2,.18); baseRotation.copy(rotation);
const uniforms={uRotation:{value:rotation},uPerspective:{value:0},uFov:{value:54},uScale4:{value:2.4},uOpacity:{value:.95}};
const vertexShader=`attribute vec4 position4;attribute vec2 surfaceUv;uniform mat4 uRotation;uniform float uPerspective,uFov,uScale4;varying vec2 vUv;varying vec3 vPos;varying float vW;void main(){vec4 p=uRotation*position4;float f=1.0;if(uPerspective>.5){float th=radians(uFov)*.5;float sr=max(sin(th),.001);float den=(p.w/uScale4+1.0/sr)*tan(th);f=1.0/max(abs(den),.075)*sign(den);}vec3 q=p.xyz*f;vUv=surfaceUv;vPos=q;vW=p.w/uScale4;gl_Position=projectionMatrix*modelViewMatrix*vec4(q,1.0);}`;
const fragmentShader=`precision highp float;varying vec2 vUv;varying vec3 vPos;varying float vW;uniform float uOpacity;vec3 palette(float t){return .55+.45*cos(6.2831853*(t+vec3(0.,.67,.33)));}void main(){vec3 dx=dFdx(vPos),dy=dFdy(vPos);vec3 n=normalize(cross(dx,dy));if(!gl_FrontFacing)n=-n;vec3 l=normalize(vec3(.5,.75,1.));float diff=.35+.65*abs(dot(n,l));float rim=pow(1.-abs(dot(n,normalize(-vPos))),2.5);vec3 col=palette(vUv.x+.08*vUv.y+.04*vW);col*=diff;col+=rim*vec3(.12,.35,.4);gl_FragColor=vec4(col,uOpacity);}`;
const material=new THREE.ShaderMaterial({uniforms,vertexShader,fragmentShader,side:THREE.DoubleSide,transparent:true,depthWrite:true});
const wireMat=new THREE.ShaderMaterial({uniforms:{...uniforms,uOpacity:{value:.24}},vertexShader,fragmentShader,side:THREE.DoubleSide,transparent:true,wireframe:true,depthWrite:false});
let surface=presets.viviani(),mesh,wire,controlGroup,resolution=96,zoom=1,projection='ortho',drag=null,autoAngle=0,normCenter=[0,0,0,0];

function geometryFromSample(s){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(s.points.length/4*3),3));g.setAttribute('position4',new THREE.BufferAttribute(s.points,4));g.setAttribute('surfaceUv',new THREE.BufferAttribute(s.uv,2));g.setIndex(new THREE.BufferAttribute(s.indices,1));g.computeBoundingSphere();return g}
function normalizeSurface(s){const lo=[Infinity,Infinity,Infinity,Infinity],hi=[-Infinity,-Infinity,-Infinity,-Infinity];for(let i=0;i<s.points.length;i+=4)for(let d=0;d<4;d++){lo[d]=Math.min(lo[d],s.points[i+d]);hi[d]=Math.max(hi[d],s.points[i+d])}normCenter=lo.map((x,d)=>(x+hi[d])*.5);let max=0;for(let i=0;i<s.points.length;i+=4)max=Math.max(max,Math.hypot(s.points[i]-normCenter[0],s.points[i+1]-normCenter[1],s.points[i+2]-normCenter[2],s.points[i+3]-normCenter[3]));const scale=2.05/Math.max(max,1e-6);for(let i=0;i<s.points.length;i+=4)for(let d=0;d<4;d++)s.points[i+d]=(s.points[i+d]-normCenter[d])*scale;uniforms.uScale4.value=2.05;return scale}
function build(){try{validateSurface(surface);const vs=Math.max(16,Math.round(resolution/2)),s=sampleSurface(surface,resolution,vs),scale=normalizeSurface(s),g=geometryFromSample(s);if(mesh){scene.remove(mesh,wire);mesh.geometry.dispose();wire.geometry.dispose()}mesh=new THREE.Mesh(g,material);wire=new THREE.Mesh(g,wireMat);wire.visible=$('wireframe').checked;scene.add(mesh,wire);buildControlNet(scale);$('degreeMetric').textContent=`${surface.degreeU} × ${surface.degreeV}`;$('controlMetric').textContent=surface.controlPoints.length*surface.controlPoints[0].length;$('sampleMetric').textContent=(resolution*vs).toLocaleString();$('resolutionOut').textContent=`${resolution} × ${vs}`;$('meshStats').textContent=`${(resolution*vs).toLocaleString()} VERTICES · ${((resolution-1)*(vs-1)*2).toLocaleString()} TRIANGLES`;$('modelBadge').textContent=(surface.name||'CUSTOM SURFACE').toUpperCase();status('NURBS surface ready.')}catch(e){status(e.message,true);console.error(e)}}
function buildControlNet(scale){if(controlGroup)scene.remove(controlGroup);controlGroup=new THREE.Group();const pts=[],tx=p=>p.map((x,d)=>(x-normCenter[d])*scale);const nu=surface.controlPoints.length,nv=surface.controlPoints[0].length;for(let i=0;i<nu;i++)for(let j=0;j<nv-1;j++)pts.push(...tx(surface.controlPoints[i][j]),...tx(surface.controlPoints[i][j+1]));for(let j=0;j<nv;j++)for(let i=0;i<nu-1;i++)pts.push(...tx(surface.controlPoints[i][j]),...tx(surface.controlPoints[i+1][j]));const lg=new THREE.BufferGeometry();lg.setAttribute('position',new THREE.BufferAttribute(new Float32Array(pts.length/4*3),3));lg.setAttribute('position4',new THREE.BufferAttribute(new Float32Array(pts),4));lg.setAttribute('surfaceUv',new THREE.BufferAttribute(new Float32Array(pts.length/2),2));const lm=new THREE.ShaderMaterial({uniforms:{...uniforms,uColor:{value:new THREE.Color(0x8ba2ad)}},vertexShader,fragmentShader:`uniform vec3 uColor;void main(){gl_FragColor=vec4(uColor,.48);}`,transparent:true,depthWrite:false});controlGroup.add(new THREE.LineSegments(lg,lm));controlGroup.visible=$('controlNet').checked;scene.add(controlGroup)}
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
function setProjection(next){projection=next;uniforms.uPerspective.value=next==='persp'?1:0;$('orthoBtn').classList.toggle('active',next==='ortho');$('perspBtn').classList.toggle('active',next==='persp');$('fovWrap').classList.toggle('disabled',next==='ortho')}
function updateStereoControls(){$('eyeSepWrap').classList.toggle('disabled',$('stereo').value==='off')}
function rotatePlane(i,j,a){const m=new THREE.Matrix4().identity(),e=m.elements,c=Math.cos(a),s=Math.sin(a);e[i*4+i]=c;e[j*4+j]=c;e[j*4+i]=-s;e[i*4+j]=s;rotation.premultiply(m)}
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,button:e.button,mode:e.button===2?'4d':'3d'}});canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;if(drag.mode==='4d'){rotatePlane(0,3,dx*.006);rotatePlane(1,3,-dy*.006)}else{rotatePlane(0,2,-dx*.005);rotatePlane(1,2,dy*.005)}});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.55,Math.min(2.6,zoom*Math.exp(-e.deltaY*.001)));$('zoom').value=zoom;$('zoomOut').textContent=zoom.toFixed(2)+'×'},{passive:false});
$('preset').addEventListener('change',e=>{surface=presets[e.target.value]();build()});$('resolution').addEventListener('change',e=>{resolution=+e.target.value;build()});$('wireframe').addEventListener('change',e=>wire.visible=e.target.checked);$('controlNet').addEventListener('change',e=>controlGroup.visible=e.target.checked);$('orthoBtn').onclick=()=>setProjection('ortho');$('perspBtn').onclick=()=>setProjection('persp');$('fov4').oninput=e=>{uniforms.uFov.value=+e.target.value;$('fovOut').textContent=e.target.value+'°'};$('zoom').oninput=e=>{zoom=+e.target.value;$('zoomOut').textContent=zoom.toFixed(2)+'×'};$('stereo').addEventListener('change',updateStereoControls);$('eyeSep').oninput=e=>{stereoCamera.eyeSep=+e.target.value;$('eyeSepOut').textContent=(+e.target.value).toFixed(2)};$('reset').onclick=()=>{rotation.copy(baseRotation);autoAngle=0;zoom=1;$('zoom').value=1;$('zoomOut').textContent='1.00×'};
$('panelToggle').onclick=()=>{const closed=$('app').classList.toggle('closed');$('panelToggle').textContent=closed?'‹':'›';$('panelToggle').setAttribute('aria-expanded',String(!closed))};
async function loadText(text,label){try{surface=validateSurface(JSON.parse(text));surface.name=surface.name||label;$('preset').value='';build()}catch(e){status('Load error: '+e.message,true)}}
$('fileInput').onchange=async e=>{const f=e.target.files[0];if(f)loadText(await f.text(),f.name)};$('loadUrl').onclick=async()=>{try{const u=$('urlInput').value.trim();if(!u)return;status('Loading…');const r=await fetch(u);if(!r.ok)throw new Error(`${r.status} ${r.statusText}`);loadText(await r.text(),u.split('/').pop())}catch(e){status('URL load error: '+e.message,true)}};
$('downloadSample').onclick=()=>{const blob=new Blob([JSON.stringify(surface,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(surface.name||'surface').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.nurbs.json';a.click();URL.revokeObjectURL(a.href)};$('copyLink').onclick=async()=>{const u=new URL(location.href);u.searchParams.set('preset',$('preset').value||'custom');u.searchParams.set('projection',projection);u.searchParams.set('stereo',$('stereo').value);u.searchParams.set('eyeSep',stereoCamera.eyeSep.toFixed(2));try{await navigator.clipboard.writeText(u);status('View URL copied.')}catch{status(u.toString())}};
function resize(){const r=canvas.parentElement.getBoundingClientRect(),w=Math.max(1,r.width|0),h=Math.max(1,r.height|0),d=renderer.getPixelRatio();if(canvas.width!==(w*d|0)||canvas.height!==(h*d|0))renderer.setSize(w,h,false);return{w,h}}
function setCameraForViewport(w,h){const base=36;if(w<h){const f=THREE.MathUtils.degToRad(base);camera.fov=THREE.MathUtils.radToDeg(2*Math.atan(Math.tan(f/2)*(h/w)))}else camera.fov=base;camera.aspect=w/h;camera.updateProjectionMatrix()}
function registerWebMcp(){const c=document.modelContext;if(!c?.registerTool)return;const register=tool=>{try{void Promise.resolve(c.registerTool(tool)).catch(console.error)}catch(e){console.error(e)}};register({name:'get_surface_state',title:'Get surface state',description:'Read the active 4D NURBS surface, projection, stereo mode and resolution.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({surface:surface.name||'Custom surface',projection,stereo:$('stereo').value,eyeSpacing:stereoCamera.eyeSep,resolution,degree:[surface.degreeU,surface.degreeV],controlPoints:surface.controlPoints.length*surface.controlPoints[0].length})});register({name:'set_surface_preset',title:'Set surface preset',description:'Display the Viviani surface, Clifford torus, or 4D spline ribbon.',inputSchema:{type:'object',properties:{preset:{type:'string',enum:['viviani','clifford','ribbon']}},required:['preset'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({preset})=>{if(!presets[preset])throw new Error('Unknown preset');$('preset').value=preset;surface=presets[preset]();build();return{surface:surface.name}}});register({name:'set_4d_projection',title:'Set 4D projection',description:'Switch between orthographic and perspective projection and optionally set the 4D field of view.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['ortho','perspective']},fov:{type:'number',minimum:1,maximum:150}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({mode,fov})=>{setProjection(mode==='perspective'?'persp':'ortho');if(fov!=null){if(!Number.isFinite(fov)||fov<1||fov>150)throw new Error('fov must be 1–150');uniforms.uFov.value=fov;$('fov4').value=fov;$('fovOut').textContent=fov+'°'}return{projection,fov:uniforms.uFov.value}}})}
let frames=0,lastFps=performance.now();function render(t){const{w,h}=resize();if($('autoRotate').checked&&!drag){const d=.0012;rotatePlane(0,3,d);rotatePlane(2,3,d*.45);autoAngle+=d}camera.position.z=7/zoom;const stereo=$('stereo').value;renderer.setScissorTest(false);renderer.setViewport(0,0,w,h);renderer.clear();if(stereo==='off'){setCameraForViewport(w,h);renderer.render(scene,camera)}else{const half=Math.floor(w/2);setCameraForViewport(half,h);camera.focus=camera.position.length();stereoCamera.update(camera);const left=stereo==='cross'?stereoCamera.cameraR:stereoCamera.cameraL,right=stereo==='cross'?stereoCamera.cameraL:stereoCamera.cameraR;renderer.setScissorTest(true);renderer.setViewport(0,0,half,h);renderer.setScissor(0,0,half,h);renderer.render(scene,left);renderer.setViewport(half,0,w-half,h);renderer.setScissor(half,0,w-half,h);renderer.render(scene,right);renderer.setScissorTest(false)}frames++;if(t-lastFps>800){$('fps').textContent=Math.round(frames*1000/(t-lastFps))+' FPS';frames=0;lastFps=t}requestAnimationFrame(render)}
const initPreset=params.get('preset');if(initPreset&&presets[initPreset]){$('preset').value=initPreset;surface=presets[initPreset]()}$('stereo').value=params.get('stereo')||'off';const initEyeSep=Number(params.get('eyeSep')??.22);stereoCamera.eyeSep=Number.isFinite(initEyeSep)?Math.max(.02,Math.min(.6,initEyeSep)):.22;$('eyeSep').value=stereoCamera.eyeSep;$('eyeSepOut').textContent=stereoCamera.eyeSep.toFixed(2);updateStereoControls();setProjection(params.get('projection')==='persp'?'persp':'ortho');build();registerWebMcp();requestAnimationFrame(render);
